<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Quiz extends Model { use HasFactory; protected $fillable=['classroom_id','created_by','title','description','instructions','opens_at','closes_at','time_limit_minutes','max_attempts','shuffle_questions','shuffle_options','passing_score','result_policy','status','published_at']; protected function casts(): array{return['opens_at'=>'datetime','closes_at'=>'datetime','published_at'=>'datetime','shuffle_questions'=>'boolean','shuffle_options'=>'boolean','passing_score'=>'decimal:2'];} public function classroom():BelongsTo{return $this->belongsTo(Classroom::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function questions():HasMany{return $this->hasMany(QuizQuestion::class)->orderBy('position');} public function attempts():HasMany{return $this->hasMany(QuizAttempt::class);} }
